ValidationRule.errorConditionFormula:
AND(NOT(SkipValidationWhileReAssigning__c), IF( OR($Profile.Name = 'CCD', $Profile.Name ='Read Only'), False, AND( NOT(ISNEW()),NOT(ISBLANK(Assigned_To__c)),
NOT($Permission.Transfer_Admin_Permission), Assigned_To__c <> $User.Id , CreatedById <> $User.Id, $Profile.Name <> 'System Administrator', $Profile.Name <> 'Integration User', $Profile.Name <> 'Corporate salesforce team', $Profile.Name <> 'Revenue Management', $Profile.Name <> 'Corporate IT team', $Profile.Name <> 'Claim User Profile' ) )
)
